import threading
import time
from worker import process_all

started = []
lock = threading.Lock()

class Boom(RuntimeError):
    pass

def process(value):
    with lock:
        started.append(value)
    if value == 1:
        time.sleep(0.02)
        raise Boom("failed")
    time.sleep(0.20)
    return value

try:
    process_all([1, 2, 3, 4, 5, 6], process)
except Boom:
    pass
else:
    raise SystemExit("worker failure was not propagated")

if len(started) > 2:
    raise SystemExit(f"pending work continued after failure: {started}")

files.classifier.py:
def classify(value):
    if value is None:
        return "missing"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        if value < 0:
            return "negative"
        if value == 0:
            return "zero"
        return "positive"
    if isinstance(value, str):
        if not value:
            return "empty"
        return "text"
    raise TypeError("unsupported value")

